const MD_range=(a,b,n)=>Array.from({length:n+1},(_,i)=>a+(b-a)*i/n);
const MD_GREY='#5C6577', MD_STEEL='#495057', MD_DARK='#343A40', MD_LIGHT='#DEE2E6';
/* mild steel curve (strain %, stress MPa): elastic to 250 MPa at 0.125 %, plateau to 2 %, hardening to 410 MPa at 15 %, necking to 350 MPa at 25 % */
const MD_steel=e=>e<=0.125?250*e/0.125:e<=2?250:e<=15?250+160*(1-Math.pow(1-(e-2)/13,2)):410-60*Math.pow((e-15)/10,2);
/* upper half of a Mohr's circle between sigma a and b on an axis at y0, with x = X(sigma) */
const MD_semi=(X,y0,a,b,col,w=5,ex='')=>{const r=(X(b)-X(a))/2;return `<path d="M${X(a)},${y0} A${r},${r} 0 0 1 ${X(b)},${y0}" fill="none" stroke="${col}" stroke-width="${w}" ${ex}/>`};
/* a stepped shaft silhouette: big section D tall from x to xs, small d tall from xs to x+w, fillet radius rf, centre line at cy */
const MD_shaft=(x,cy,w,xs,D,d,rf,col=MD_STEEL)=>`<path d="M${x},${cy-D/2} L${xs},${cy-D/2} L${xs},${cy-d/2-rf} Q${xs},${cy-d/2} ${xs+rf},${cy-d/2} L${x+w},${cy-d/2} L${x+w},${cy+d/2} L${xs+rf},${cy+d/2} Q${xs},${cy+d/2} ${xs},${cy+d/2+rf} L${xs},${cy+D/2} L${x},${cy+D/2} Z" fill="${col}" fill-opacity=".85" stroke="${MD_DARK}" stroke-width="2"/>`;
/* von Mises ellipse sigma1^2 - sigma1 sigma2 + sigma2^2 = 1, and the Tresca hexagon, at centre (cx,cy), k px per Syt */
const MD_vm=(cx,cy,k)=>MD_range(0,2*Math.PI,96).map(t=>{const u=Math.SQRT2*Math.cos(t),v=Math.sqrt(2/3)*Math.sin(t);return [cx+k*(u+v)/Math.SQRT2,cy-k*(u-v)/Math.SQRT2]});
const MD_hex=(cx,cy,k)=>[[1,0],[1,1],[0,1],[-1,0],[-1,-1],[0,-1],[1,0]].map(([a,b])=>[cx+k*a,cy-k*b]);

